Проблема в том, что вы неправильно применяете поворот камеры к позиции игрока. Вот исправленная версия функции:

```cpp
void addPlayersToRadar(Player * player){
    Vector3 pos = player->position;
    Vector3 myPos = GetPosition(myPlayer);

    // Вычисляем вектор от нас к игроку
    Vector3 toPlayer = pos - myPos;

    // Получаем угол поворота камеры (обычно по оси Y для вида сверху)
    Quaternion cameraRotation = GetRotation(get_main());

    // Конвертируем кватернион в угол поворота по Y (yaw)
    float cameraYaw = atan2(2.0f * (cameraRotation.w * cameraRotation.y + cameraRotation.x * cameraRotation.z),
                            1.0f - 2.0f * (cameraRotation.y * cameraRotation.y + cameraRotation.z * cameraRotation.z));

    // Применяем поворот к координатам на радаре
    float rotatedX = toPlayer.x * cos(-cameraYaw) - toPlayer.z * sin(-cameraYaw);
    float rotatedZ = toPlayer.x * sin(-cameraYaw) + toPlayer.z * cos(-cameraYaw);

    // Масштабируем для радара (например, 1 юнит в игре = 1 пиксель на радаре)
    float radarScale = 1.0f; // Настройте под ваш масштаб
    rotatedX *= radarScale;
    rotatedZ *= radarScale;

    // Ограничиваем радиус радара
    float distance = sqrt(rotatedX * rotatedX + rotatedZ * rotatedZ);
    float maxRadius = 180.0f;

    if(distance > maxRadius){
        rotatedX = (rotatedX / distance) * maxRadius;
        rotatedZ = (rotatedZ / distance) * maxRadius;
    }

    // Рисуем точку на радаре
    bg->AddCircleFilled({radar_center.x + rotatedX, 
                        radar_center.y - rotatedZ}, // Минус, так как ось Y инвертирована
                        5, 
                        ImColor(255, 0, 0, 255));
}
```

Альтернативный вариант с использованием матрицы поворота:

```cpp
void addPlayersToRadar(Player * player){
    Vector3 pos = player->position;
    Vector3 myPos = GetPosition(myPlayer);

    // Вектор от игрока к цели
    Vector3 diff = pos - myPos;

    // Получаем forward вектор камеры
    Vector3 cameraForward = GetCameraForward(get_main());

    // Вычисляем угол камеры относительно севера (ось Z)
    float cameraAngle = atan2(cameraForward.x, cameraForward.z);

    // Поворачиваем координаты относительно направления камеры
    float cosAngle = cos(-cameraAngle);
    float sinAngle = sin(-cameraAngle);

    float rotatedX = diff.x * cosAngle - diff.z * sinAngle;
    float rotatedZ = diff.x * sinAngle + diff.z * cosAngle;

    // Масштабирование для радара
    float radarScale = 1.0f; // Подберите нужный масштаб

    // Ограничение по радиусу
    float maxRadius = 180.0f;
    float distance = sqrt(rotatedX * rotatedX + rotatedZ * rotatedZ);

    if(distance > maxRadius){
        float scale = maxRadius / distance;
        rotatedX *= scale;
        rotatedZ *= scale;
    }

    // Отрисовка на радаре
    ImVec2 radarPos = {
        radar_center.x + rotatedX * radarScale,
        radar_center.y - rotatedZ * radarScale  // Y инвертирован
    };

    bg->AddCircleFilled(radarPos, 5, ImColor(255, 0, 0, 255));
}
```

Ключевые изменения:
1. Правильное вычисление относительной позиции
2. Корректное применение поворота камеры
3. Инверсия оси Y для правильного отображения
4. Ограничение по радиусу после поворота

